const main=document.querySelector('main');
const TYPE_PRESETS=[
 {id:'instrument-source',name:'Instrument / Source',title:'Instrument Sans 600',body:'Source Serif 4 400'},
 {id:'source-plex',name:'Source / Plex',title:'Source Serif 4 600',body:'IBM Plex Sans 400'},
 {id:'space-newsreader',name:'Space / Newsreader',title:'Space Grotesk 600',body:'Newsreader 400'},
 {id:'newsreader-work',name:'Newsreader / Work',title:'Newsreader 500',body:'Work Sans 400'}
];
const PALETTE_PRESETS=[
 {id:'ink-white',name:'Ink / White'},
 {id:'mineral-night',name:'Mineral / Mist'},
 {id:'photo-black',name:'Black / Silver'},
 {id:'mist-paper',name:'Mist / Mineral'}
];
const PREFERENCE_KEY='journal-experiment-preferences';
const defaultPreferences={type:'instrument-source',palette:'ink-white'};
function validPreference(value,presets,fallback){return presets.some(p=>p.id===value)?value:fallback}
function loadPreferences(){
 try{
  const saved=JSON.parse(localStorage.getItem(PREFERENCE_KEY)||'{}');
  return {type:validPreference(saved.type,TYPE_PRESETS,defaultPreferences.type),palette:validPreference(saved.palette,PALETTE_PRESETS,defaultPreferences.palette)};
 }catch{return {...defaultPreferences}}
}
let preferences=loadPreferences();
function applyPreferences(next=preferences,persist=false){
 preferences={type:validPreference(next.type,TYPE_PRESETS,defaultPreferences.type),palette:validPreference(next.palette,PALETTE_PRESETS,defaultPreferences.palette)};
 document.documentElement.dataset.type=preferences.type;
 document.documentElement.dataset.palette=preferences.palette;
 const experimentRoot=document.querySelector('.experiment');
 if(experimentRoot){experimentRoot.dataset.type=preferences.type;experimentRoot.dataset.palette=preferences.palette}
 if(persist){try{localStorage.setItem(PREFERENCE_KEY,JSON.stringify(preferences))}catch{}}
}
applyPreferences();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=d=>d.replaceAll('-',' · ');
const indexDateLabel=d=>`${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(d.slice(5,7))-1]} ${d.slice(8,10)}`;
const longDateLabel=d=>`${['January','February','March','April','May','June','July','August','September','October','November','December'][Number(d.slice(5,7))-1]} ${Number(d.slice(8,10))}, ${d.slice(0,4)}`;
const monthLabel=d=>`${['January','February','March','April','May','June','July','August','September','October','November','December'][Number(d.slice(5,7))-1]} ${d.slice(0,4)}`;
const timeLabel=t=>t.slice(11,19);
const zoneLabel=t=>`UTC${t.slice(-6)}`;
const sortKey=t=>t.timestamp||`${t.date}T00:00:00+08:00`;
const readTime=t=>Math.max(1,Math.ceil([...(t.body||[]),...(t.more||[])].join(' ').trim().split(/\s+/).filter(Boolean).length/200));
const conceptLink=c=>`<a href="#/concept/${encodeURIComponent(c)}">${esc(c)}</a>`;
function entry(t){return `<li class="entry"><div><time datetime="${esc(t.date)}">${indexDateLabel(t.date)}</time><h2 class="entry-title"><a href="#/thought/${encodeURIComponent(t.slug)}">${esc(t.title)}</a></h2><div class="concepts">${t.concepts.map(conceptLink).join('')}</div></div><span class="form">${esc(t.form)}</span></li>`}
function archive(kind='chronology',value=''){
 const filtered=thoughts.filter(t=>!value||(kind==='concept'?t.concepts.includes(value):t.form===value));
 const groups=[...new Set(filtered.map(t=>t.date.slice(0,4)))];
 const choices=kind==='concept'?[...new Set(thoughts.flatMap(t=>t.concepts))].sort((a,b)=>a.localeCompare(b)):['essay','note','poem','fragment'];
 main.innerHTML=`<div class="archive-top grid"><h1 class="section-label">Index</h1><nav class="view-nav" aria-label="Archive view">${['chronology','concept','form'].map(k=>`<a href="#/${k==='chronology'?'archive':k}" ${k===kind?'aria-current="page"':''}>${k[0].toUpperCase()+k.slice(1)}</a>`).join('')}</nav><span class="total">${filtered.length.toString().padStart(2,'0')} thoughts · 2025–2026</span>${kind!=='chronology'?`<div class="filter-index" aria-label="${kind} filters">${choices.map(c=>`<a class="${value===c?'active':''}" href="#/${kind}/${encodeURIComponent(c)}" ${value===c?'aria-current="true"':''}>${esc(c)}<sup>${thoughts.filter(t=>kind==='concept'?t.concepts.includes(c):t.form===c).length}</sup></a>`).join('')}</div>`:''}</div><div class="archive grid"><div class="archive-content">${groups.map(y=>`<section class="year-group" aria-label="${y}"><h2 class="year">${y}</h2><ol class="entries">${filtered.filter(t=>t.date.startsWith(y)).map(entry).join('')}</ol></section>`).join('')}</div><aside class="archive-aside"><p>Essays, notes,<br>poems & fragments.</p><p><em>A thought is rarely<br>finished.</em></p></aside></div>`;
}
function streamStamp(t){
 const url=`#/thought/${encodeURIComponent(t.slug)}`;
 if(!t.timestamp)return `<a class="timestamp" href="${url}" aria-label="Permalink to ${esc(t.title)}"><time datetime="${esc(t.date)}">${esc(longDateLabel(t.date))}</time></a>`;
 return `<a class="timestamp" href="${url}" aria-label="Permalink to ${esc(t.title)}"><time datetime="${esc(t.timestamp)}">${timeLabel(t.timestamp)}</time></a><time datetime="${esc(t.timestamp)}">${esc(longDateLabel(t.date))}</time><span>${zoneLabel(t.timestamp)}</span>`;
}
function streamEntry(t){
 const body=t.body.map(p=>`<p>${esc(p)}</p>`).join('');
 if(t.form==='essay')return `<article class="stream-entry essay-entry"><div class="entry-stamp">${streamStamp(t)}</div><div class="entry-content"><p class="entry-kind">Essay · ${readTime(t)} min read</p><h2 class="entry-title"><a href="#/thought/${encodeURIComponent(t.slug)}">${esc(t.title)}</a></h2><p class="entry-excerpt">${esc(t.body[0])}</p></div></article>`;
 return `<article class="stream-entry ${t.form==='fragment'?'fragment-entry':'note-entry'}"><div class="entry-stamp">${streamStamp(t)}</div><div class="entry-content${t.form==='poem'?' poem':''}"><p class="entry-kind">${esc(t.form[0].toUpperCase()+t.form.slice(1))}</p>${body}</div></article>`;
}
function journal(filter='all'){
 const allowed=['fragment','note','essay'];
 const active=allowed.includes(filter)?filter:'all';
 const ordered=thoughts.filter(t=>active==='all'||t.form===active).sort((a,b)=>sortKey(b).localeCompare(sortKey(a)));
 const months=[...new Set(ordered.map(t=>t.date.slice(0,7)))];
 const filters=[['all','All'],['fragment','Fragments'],['note','Notes'],['essay','Essays']];
 main.innerHTML=`<div class="journal"><header class="journal-intro"><p class="eyebrow">The journal</p><h1>a home for thoughts</h1><p>Essays and passing thoughts, in order of appearance.</p></header><nav class="journal-filters" aria-label="Filter journal">${filters.map(([id,label])=>`<a data-journal-filter="${id}" href="${id==='all'?'#/':`#/journal/${id}`}" ${id===active?'aria-current="page"':''}>${label}<sup>${id==='all'?thoughts.length:thoughts.filter(t=>t.form===id).length}</sup></a>`).join('')}</nav><div class="stream">${months.map((month,i)=>`<section class="stream-month" aria-label="${monthLabel(`${month}-01`)}"><div class="stream-header"><span>${monthLabel(`${month}-01`)}</span>${i===0?'<span>Newest first</span>':''}</div>${ordered.filter(t=>t.date.startsWith(month)).map(streamEntry).join('')}</section>`).join('')}</div></div>`;
}
function article(slug){const t=thoughts.find(t=>t.slug===slug);if(!t){main.innerHTML='<div class="simple"><h1>Thought not found</h1><p><a href="#/">Return to the journal</a></p></div>';return}document.title=`${t.title} — a home for thoughts`;const related=thoughts.filter(x=>x!==t&&x.concepts.some(c=>t.concepts.includes(c))).slice(0,3);if(!related.length)related.push(thoughts[0]);const published=t.timestamp?`${timeLabel(t.timestamp)} · ${dateLabel(t.date)} · ${zoneLabel(t.timestamp)}`:dateLabel(t.date);main.innerHTML=`<article class="reading grid"><a class="back" href="#/">← Journal</a><header class="article-heading"><h1>${esc(t.title)}</h1><div class="article-meta"><time datetime="${esc(t.timestamp||t.date)}">${published}</time><span>${esc(t.form)}</span><div class="concepts">${t.concepts.map(conceptLink).join('')}</div></div></header><div class="prose ${t.form==='poem'?'poem':''}">${t.body.map(p=>`<p>${esc(p)}</p>`).join('')}</div>${t.note?`<aside class="margin-note"><span>01 / In the margin</span>${esc(t.note)}</aside>`:''}${t.more?`<div class="prose"><h2>${esc(t.heading)}</h2>${t.more.map(p=>`<p>${esc(p)}</p>`).join('')}</div>`:''}<section class="related"><h2>Related thoughts</h2>${related.map(x=>`<a href="#/thought/${encodeURIComponent(x.slug)}">${esc(x.title)}</a>`).join('')}</section></article>`}
function simple(page){main.innerHTML=page==='about'?`<div class="simple grid"><h1 class="section-label">About</h1><div class="prose"><p>A place to put things into words, and return to them later.</p><p>This archive moves between design, technology, Buddhism, attention, and the small details of ordinary life. Sometimes an essay. Sometimes a few lines.</p><p>The concepts beside each entry are ways of finding connections. They will probably change as the collection grows.</p><p><a href="#/archive">Browse the archive by date, concept, or form.</a></p><p class="small-note">Prototype copy. The entries in this version are sample writing for exploring the interface.</p></div></div>`:`<div class="simple grid"><h1 class="section-label">Now</h1><div class="prose"><p class="small-note" style="margin-top:0!important">10 September 2026 · Sample snapshot</p><h2>Reading</h2><p>Returning to the notes in the margins of books I thought I had finished.</p><h2>Thinking about</h2><p>The difference between paying attention and trying to be attentive.</p><h2>Working on</h2><p>A home for these thoughts. Finding a structure that leaves room for things to change.</p><h2>Listening to</h2><p>The city with the window open.</p></div></div>`}
function experiment(){
 const option=(kind,p)=>`<label class="experiment-option" data-${kind}-option="${p.id}"><input type="radio" name="${kind}" value="${p.id}" ${preferences[kind]===p.id?'checked':''}><span><strong>${p.name}</strong>${kind==='type'?`<small>Title: ${p.title} · Body: ${p.body}</small>`:''}</span></label>`;
 main.innerHTML=`<div class="experiment" data-type="${preferences.type}" data-palette="${preferences.palette}"><header class="experiment-heading"><p class="eyebrow">Type & colour</p><h1>Experiment</h1></header><form class="experiment-controls"><fieldset class="experiment-group"><legend>Typography</legend><div class="experiment-options">${TYPE_PRESETS.map(p=>option('type',p)).join('')}</div></fieldset><fieldset class="experiment-group"><legend>Palette</legend><div class="experiment-options">${PALETTE_PRESETS.map(p=>option('palette',p)).join('')}</div></fieldset><button class="experiment-reset" type="button">Reset to Instrument / Source and Ink / White</button></form><section class="experiment-preview" aria-live="polite" aria-label="Live specimen"><p class="experiment-kicker">Live specimen</p><article class="experiment-essay"><p class="entry-kind">Essay · 1 min read</p><h2 class="experiment-title">Before you judge</h2><p class="experiment-deck">There is a moment before judgment when a thing is allowed to be itself. It is usually a very short moment.</p><p class="experiment-meta">September 7, 2026 · attention, perception</p><div class="experiment-prose"><p>Then we reach for a comparison. What it should have been, what someone else would have done, what we would have done—under circumstances we have quietly improved for ourselves.</p><p>Standards are useful. They help us notice the difference between what is and what might be.</p></div><a class="experiment-link" href="#/thought/before-you-judge">Read the essay</a></article><article class="experiment-fragment"><div class="entry-stamp"><a class="timestamp" href="#/thought/the-light-changed-first"><time datetime="2026-09-14T17:42:08+08:00">17:42:08</time></a><time datetime="2026-09-14T17:42:08+08:00">September 14, 2026</time><span>UTC+08:00</span></div><div><p class="entry-kind">Fragment</p><p>The room did not become quieter. The light changed first, and then I noticed how long I had been listening.</p></div></article></section></div>`;
 main.querySelector('.experiment-controls').addEventListener('change',e=>{if(!e.target.matches('input[type="radio"]'))return;applyPreferences({...preferences,[e.target.name]:e.target.value},true)});
 main.querySelector('.experiment-reset').addEventListener('click',()=>{try{localStorage.removeItem(PREFERENCE_KEY)}catch{}applyPreferences(defaultPreferences);experiment()});
}
function render(){const [page='',raw='']=location.hash.slice(2).split('/');let value;try{value=decodeURIComponent(raw)}catch{value=''}document.title='a home for thoughts';document.querySelectorAll('[data-nav]').forEach(a=>{const section=page==='exp'?'exp':(['about','now'].includes(page)?page:'index');const active=a.dataset.nav===section;if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(page==='thought')article(value);else if(['about','now'].includes(page))simple(page);else if(page==='exp')experiment();else if(page==='journal')journal(value);else if(['archive','concept','form'].includes(page))archive(['concept','form'].includes(page)?page:'chronology',value);else journal()}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);main.focus({preventScroll:true})});document.querySelector('#top-link').addEventListener('click',e=>{e.preventDefault();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})});render();
